function dir$qlcuochop(p){
  this.constructor(p);
}
dir$qlcuochop.prototype = new DirEvent();
function getSystemTime(format) {
    return new Promise(function(resolve, reject) {
        $.ajax({
            type: "POST",
            url: "/Main/Defaults.aspx/GetSystemTime",
            contentType: "application/json; charset=utf-8",
            dataType: "json",
            data: JSON.stringify({ format: format }),
            success: function(response) {
                var systemTime = response.d;
                resolve(systemTime);
            },
            error: function(error) {
                reject(error);
            }
        });
    });
}
function getTime(p, className) {
	const inputEl = document.querySelector(`input.${className}`);
	console.log(inputEl);
    if (!inputEl) return;

    let isValid = false;

    inputEl.addEventListener("input", function (e) {
        let raw = e.target.value.replace(/\D/g, "").slice(0, 4); // Giữ lại 4 chữ số đầu
        let formatted = raw;

        if (raw.length >= 3) {
            formatted = `${raw.slice(0, 2)}:${raw.slice(2, 4)}`;
        }

        e.target.value = formatted;

		const [h, m] = formatted.split(":").map(Number);
        isValid = Number.isInteger(h) && Number.isInteger(m) && h >= 0 && h <= 23 && m >= 0 && m <= 59;

    });

    inputEl.addEventListener("blur", async (e) => {
        if (!isValid && e.target.value.trim() !== "") {
            try {
                const [hh, mm] = await Promise.all([
                    getSystemTime("HH"),
                    getSystemTime("mm")
                ]);
                e.target.value = `${hh}:${mm}`;
            } catch (err) {
                console.error("Lỗi lấy giờ hệ thống:", err);
            }
        } else {
            console.log("✅ Giờ hợp lệ:", e.target.value);
        }
    });
}
dir$qlcuochop.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
  document._dir = this._dir;
}
dir$qlcuochop.prototype.afterInit = function(renderType){
    var p = this._dir,g = p.options.parent;

	getTime(p, 'gio_bd');
	getTime(p, 'gio_kt');

	dir$qlcuochopLoadMaCuocHop(p);
	dir$qlcuochopDisabledMasterField(p, g);
}

function dir$qlcuochopLoadMaCuocHop(p){
	var maCuochop = p.valForm('ma_cuochop');

	if(p.options.action == 'NEW') {	
		p.request('LoadMaCuocHop', '', ['ngay_hop']);
	}
}

dir$qlcuochop.prototype.formFieldValueChange = function(o, cF, v) {
    var p = this._dir;
	switch (cF){
		case 'ngay_hop':
			dir$qlcuochopLoadMaCuocHop(p);
		break;

		default:
		  break;
	}
};

function dir$qlcuochopDisabledMasterField(p){
	var maCuochop = p.valForm('ma_cuochop');
	if (maCuochop !== '') {
		p.setDisabled('ngay_hop', true);
	}
	else {
		p.setDisabled('ngay_hop', false);
	}
}






